/* Pale surfaces and feature edges, prepared once and reversible without rebuilding the city. */
window.createAtlasWireframe=function(THREE,scene,movingRoots,camera){
 const button=document.querySelector('#wireframe-toggle'),caption=button?.querySelector?.('.wireframe-label'),records=[],staticRoot=new THREE.Group(),dynamicLines=[],styles=new Map(),edgeCache=new Map();staticRoot.name='Clean blue architectural outlines';staticRoot.visible=false;scene.add(staticRoot);
 const ink=new THREE.LineBasicMaterial({color:'#536776',transparent:true,opacity:.72,depthWrite:false,toneMapped:false});const lineStyles=new Map([['none',ink]]);let enabled=false,preparing=null,ready=false,segments=0,surfacesActive=false,transitionSerial=0,transitioning=false,warmed=false;

 ink.onBeforeCompile=shader=>{shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 vPencilPosition;').replace('#include <begin_vertex>','#include <begin_vertex>\nvPencilPosition=position;').replace('#include <project_vertex>','#include <project_vertex>\ngl_Position.z-=.0000005*gl_Position.w;');shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 vPencilPosition;').replace('#include <color_fragment>','#include <color_fragment>\nfloat pencilPressure=.82+.18*sin(dot(vPencilPosition,vec3(17.1,23.7,13.3)));diffuseColor.a*=pencilPressure;');};ink.customProgramCacheKey=()=> 'hydrogen-pencil-outline-v1';
 function lineStyle(originals){const original=originals.find(material=>material.clippingPlanes?.length)??originals[0],planes=original.clippingPlanes??[],key=planes.length?JSON.stringify([!!original.clipIntersection,...planes.map(p=>[p.normal.x,p.normal.y,p.normal.z,p.constant])]):'none';if(!lineStyles.has(key)){const material=ink.clone();material.clippingPlanes=planes;material.clipIntersection=original.clipIntersection;material.onBeforeCompile=ink.onBeforeCompile;material.customProgramCacheKey=ink.customProgramCacheKey;lineStyles.set(key,material);}return lineStyles.get(key);}
 function update(){button?.setAttribute('aria-pressed',String(enabled));button?.setAttribute('aria-label',enabled?'Return to solid view':'Show blue outline view');if(caption)caption.textContent=preparing?'Preparing…':enabled?'Solid view':'Wireframe';if(button)button.disabled=!!preparing;}
 function pale(original){if(styles.has(original))return styles.get(original);const hsl={};original.color?.getHSL(hsl);const color=original.map?'#ffffff':hsl.h>.42&&hsl.h<.74?'#e9edea':hsl.h>.15&&hsl.h<.42?'#ecefe8':'#f5f3ed',material=original.clone();material.name='Pale blueprint surface';material.userData.outlineColor=new THREE.Color(color);styles.set(original,material);return material;}
 function skipped(mesh){if(mesh.userData.staticBatchSource)return true;for(let parent=mesh;parent;parent=parent.parent)if(parent.userData.outlineExcluded)return true;return false;}
 async function prepare(){if(ready)return;scene.updateMatrixWorld(true);const meshes=[];scene.traverse(mesh=>{if(mesh.isMesh&&!skipped(mesh))meshes.push(mesh);});const staticBatches=new Map(),movingBatches=new Map();let lastYield=performance.now();
  function append(batches,key,material,array){if(!batches.has(key))batches.set(key,new Map());const materials=batches.get(key);if(!materials.has(material))materials.set(material,[]);materials.get(material).push(array);}
  for(const mesh of meshes){const originals=Array.isArray(mesh.material)?mesh.material:[mesh.material];records.push({mesh,original:mesh.material,pale:Array.isArray(mesh.material)?originals.map(pale):pale(mesh.material)});if(!mesh.isInstancedMesh&&mesh.geometry?.attributes?.position){if(!edgeCache.has(mesh.geometry))edgeCache.set(mesh.geometry,new THREE.EdgesGeometry(mesh.geometry,32));const edge=edgeCache.get(mesh.geometry);if(edge.attributes.position.count){const material=lineStyle(originals);let movingRoot=null;for(let parent=mesh;parent;parent=parent.parent)if(movingRoots.has(parent)){movingRoot=parent;break;}if(movingRoot){mesh.geometry.computeBoundingBox();const size=mesh.geometry.boundingBox.getSize(new THREE.Vector3());if(Math.max(size.x,size.y,size.z)>=.6){const transform=movingRoot.matrixWorld.clone().invert().multiply(mesh.matrixWorld),local=edge.clone().applyMatrix4(transform);append(movingBatches,movingRoot,material,local.attributes.position.array);segments+=edge.attributes.position.count/2;}}else{const world=edge.clone().applyMatrix4(mesh.matrixWorld);append(staticBatches,staticRoot,material,world.attributes.position.array);segments+=edge.attributes.position.count/2;}}}if(performance.now()-lastYield>8){await new Promise(resolve=>requestAnimationFrame(resolve));lastYield=performance.now();}}
  for(const [batches,moving]of[[staticBatches,false],[movingBatches,true]])for(const [root,materials]of batches)for(const [material,arrays]of materials){const merged=new Float32Array(arrays.reduce((sum,array)=>sum+array.length,0));let offset=0;for(const array of arrays){merged.set(array,offset);offset+=array.length;}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(merged,3));geometry.computeBoundingSphere();const line=new THREE.LineSegments(geometry,material);line.name=moving?'Batched moving blue feature edges':'Batched static blue feature edges';line.visible=!moving;line.renderOrder=2;line.raycast=()=>{};root.add(line);if(moving)dynamicLines.push(line);}ready=true;
 }
 async function preload(){if(ready)return;if(!preparing){preparing=prepare();update();}const task=preparing;try{await task;}finally{if(preparing===task){preparing=null;update();}}}
 async function warmup(renderer,camera){await preload();if(warmed)return;const nodes=[];scene.traverse(node=>{if(node.isMesh||node.isLine||node.isPoints)nodes.push({node,visible:node.visible,material:node.material});});const rootVisible=staticRoot.visible,shadowPending=renderer.shadowMap.needsUpdate,scissor=renderer.getScissor(new THREE.Vector4()),scissorTest=renderer.getScissorTest();try{for(const entry of nodes)entry.node.visible=false;for(const record of records)record.mesh.material=record.pale;staticRoot.visible=true;renderer.shadowMap.needsUpdate=false;renderer.setScissor(0,0,1,1);renderer.setScissorTest(true);const resources=[...records.map(r=>r.mesh),...staticRoot.children,...dynamicLines];for(let i=0;i<resources.length;i+=24){const batch=resources.slice(i,i+24);for(const node of batch)node.visible=true;renderer.render(scene,camera);for(const node of batch)node.visible=false;await new Promise(resolve=>requestAnimationFrame(resolve));}warmed=true;}finally{for(const entry of nodes){entry.node.visible=entry.visible;entry.node.material=entry.material;}staticRoot.visible=rootVisible;renderer.shadowMap.needsUpdate=shadowPending;renderer.setScissor(scissor);renderer.setScissorTest(scissorTest);}}

 async function setEnabled(value,timing={}){value=!!value;if(value&&!ready)await preload();if(!value&&!surfacesActive){enabled=false;update();return;}const token=++transitionSerial;enabled=value;transitioning=true;const fromInk=surfacesActive?ink.opacity:0,starts=[];for(const [original,palette]of styles){if(!surfacesActive){const color=palette.userData.outlineColor;palette.copy(original);palette.userData.outlineColor=color;palette.name='Pale blueprint surface';}starts.push({original,palette,color:palette.color?.clone(),roughness:palette.roughness,metalness:palette.metalness});}for(const record of records)record.mesh.material=record.pale;surfacesActive=true;staticRoot.visible=true;for(const line of dynamicLines)line.visible=true;for(const material of lineStyles.values())material.opacity=fromInk;document.body.classList.toggle('wireframe-view',enabled);update();const duration=timing.duration??(globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches?0:1350),start=timing.start??performance.now();await new Promise(resolve=>{function step(now){if(token!==transitionSerial){resolve();return;}const t=duration?Math.min(1,(now-start)/duration):1,k=t*t*t*(10+t*(-15+6*t));for(const item of starts){const {original,palette,color}=item;if(color)palette.color.lerpColors(color,value?palette.userData.outlineColor:original.color,k);if(palette.emissive&&original.emissive){palette.emissive.copy(original.emissive);palette.emissiveIntensity=original.emissiveIntensity;}if(original.envMapIntensity!==undefined)palette.envMapIntensity=original.envMapIntensity;palette.opacity=original.opacity;if(item.roughness!==undefined)palette.roughness=THREE.MathUtils.lerp(item.roughness,value?.9:original.roughness,k);if(item.metalness!==undefined)palette.metalness=THREE.MathUtils.lerp(item.metalness,value?Math.min(.08,original.metalness):original.metalness,k);}for(const material of lineStyles.values())material.opacity=THREE.MathUtils.lerp(fromInk,value?.72:0,k);if(t<1)requestAnimationFrame(step);else{transitioning=false;if(!value){for(const record of records)record.mesh.material=record.original;surfacesActive=false;staticRoot.visible=false;for(const line of dynamicLines)line.visible=false;}update();resolve();}}requestAnimationFrame(step);});}
 button?.addEventListener('click',()=>setEnabled(!enabled));update();return{prepare:preload,warmup,setEnabled,toggle:()=>setEnabled(!enabled),get state(){return{enabled,ready,transitioning,preparing:!!preparing,segments,warmed,clippedOutlineDrawCalls:[...staticRoot.children,...dynamicLines].filter(line=>line.material.clippingPlanes?.length).length,staticDrawCalls:staticRoot.children.length,dynamicDrawCalls:dynamicLines.length};}};
};
